-- GENERATED by `wfj generate` from data/gossip/gossip-73.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["73010bae05a9562e"] = { "Stalliere", "." },
  ["7305bd8ea8ee599c"] = { "Puoi andare, {name}.", "." },
  ["730988ab1f410266"] = { "Ho un grande debito con te, {class}. Forse posso aiutare la tua causa.", "." },
  ["730b8716fd68f667"] = { "Ok! Cominciamo!", "." },
  ["730bbec89eed158c"] = { "Non addestro chiunque! Prima dovrai svolgere un compito!", "." },
  ["730e4d9ce61dbc83"] = { "I Paragons of Power sono resti dell'antico Impero Gurubashi. Noi Zandalari li cerchiamo: non solo hanno per noi un enorme valore da collezione, ma crediamo anche che racchiudano il mojo più potente usato dal vecchio Impero.\n\nA ⟦Zul'Gurub=Zul'gurub⟧ puoi aspettarti di trovare tre tipi di Paragons: monete, gioielli e oggetti primordiali. Portaceli nelle quantità che chiediamo e in cambio riceverai alcuni dei migliori oggetti mai creati da noi Zandalari.\n\nPuoi contarci, amico!", "." },
  ["731470e90d70f063"] = { "Qui potrebbe esserci un pericolo dietro ogni angolo.", "." },
  ["731632f999e325be"] = { "Ho notato che quando getto qualcosa in quest'acqua, quando lo ripesco è incredibilmente migliorato.", "." },
  ["731860393c93ece7"] = { "Se qualcuno ha rimesso insieme il magico scettro delle sabbie, la guerra con gli insetti è vicina. Non vedo l'ora, {class}! Gli ultimi nostri beni bellici sono in viaggio verso ⟦Silithus=Silitus⟧ e dovrebbero arrivare entro $2113w giorni. Va' e porta onore all'⟦Horde=Orda⟧!", "." },
  ["732faeabd29a7578"] = { "Incantamento", "." },
  ["7339521ec497a4dc"] = { "%s raccoglie l'erba da terra.", "." },
  ["733a4a5ff9907240"] = { "La tua abilità non è priva di merito, ma devo metterti alla prova un'ultima volta prima di prenderti con me.", "." },
  ["733d6511fbdd4ae4"] = { "Basta!", "." },
  ["733e95cce530931e"] = { "Il fatto che tu sia qui è un primo passo... una scelta giusta, se vogliamo, per aiutare lo Stormo di Ysera.\n\nPotresti essere qui solo per il richiamo del guadagno personale, o perché ti senti moralmente <obbligato/obbligata>. Nessuna delle due ragioni conta di per sé, ma in realtà entrambe sono fondamentali per questo scopo: l'agonia che Eranikus patisce è ciò che mi ha destato dal mio Sogno, e ora è mio compito porre fine al suo tormento. Ti chiedo di aiutarmi in questa missione.", "." },
  ["7340ad087d04a0a2"] = { "Hai già trovato un ingegnere esperto che faccia un tubo di bronzo?", "." },
  ["73433bdb1e2b8bdb"] = { "Questi fuochi d'artificio fanno proprio un bel BUM, non trovi?", "." },
  ["7343b82a90bfad68"] = { "Balai Lok'Wein di ⟦Brackenwall Village=Felcimura⟧, ad ⟦Dustwallow Marsh=Acquemorte⟧, vende un manuale che dovrai studiare per migliorare le tue abilità!", "." },
  ["734682c1f5749732"] = { "Sì, Okla, puoi. Ma non allontanarti troppo da casa.", "." },
  ["735a0cf25aff8c8a"] = { "Salute, {class} {race}. Sono il comandante Stronghammer, l'ambasciatore che rappresenta qui l'⟦Alliance=Alleanza⟧. Se hai domande sullo stato delle raccolte dell'⟦Alliance=Alleanza⟧ per lo sforzo bellico di ⟦Ahn'Qiraj=Ahn'qiraj⟧, <ragazzo/ragazza>, non esitare a chiedere.", "." },
  ["735af90a6d531be6"] = { "Che dolci della Veglia delle Ombre hai in vendita?", "." },
  ["735eaefcf97f8590"] = { "{name}, non hai ancora assaltato le quattro basi. Torna da me quando avrai completato i tuoi obiettivi.", "." },
  ["735eddbed72f7cc4"] = { "Cosa posso comprare?", "." },
  ["736009cf8cb76919"] = { "Hai superato le mie modeste capacità. Cerca l'elfa della notte Ainethil alla ⟦Craftsmen's Terrace=Terrazza degli Artigiani⟧ di Darnassus. Lei può insegnarti di più. Vorrei solo poter venire con te.", "." },
  ["7365f99fff8307b8"] = { "Eccoti un altro carico!", "." },
  ["736a56ebf1be89c9"] = { "%s beve la cura portata da {name}.", "." },
  ["736a9896bd7e6241"] = { "Vuoi diventare ingegnere, eh? Beh, per Muradin, sei nel posto giusto!", "." },
  ["7373b6aa6e76bdad"] = { "Queste terre non sono ormai impossibili da guarire? Sembrano proprio malridotte.", "." },
  ["7379594f5a1af604"] = { "La mia risposta è Malygos.", "." },
  ["737de85c9451e4e4"] = { "Va' con grazia, e che la magia della Dama ti protegga.", "." },
  ["737fcb788492b89d"] = { "Questo atto di sfida non resterà impunito. Tu e il tuo mondo morirete!", "." },
  ["7380fc5c7ba6df8d"] = { "È inutile. Se ne tagli uno, ne crescono altri due.", "." },
  ["73811c8b4cb545b0"] = { "Salve, {class}, e benvenut<o/a> alla ⟦Darkmoon Faire=Fiera di Lunacupa⟧. Qui alla fiera c'è così tanto da fare che per chi viene per la prima volta può essere un po' travolgente. Per questo sono qui ad aiutare. Hai qualche domanda?", "." },
  ["738484af430ceab1"] = { "Ben <trovato/trovata>, <amico/amica>. Sono l'ufficiale Garush, e faccio parte con orgoglio di un'organizzazione presente in tutto il mondo, nota come ⟦Argent Dawn=Alba d'Argento⟧. La nostra causa è combattere con rapidità e senza pietà ogni elemento del male che emerga ad Azeroth. Non siamo un organismo politico, né desideriamo mai diventarlo. La nostra causa è una sola, e per questo chiamiamo amici sia l'⟦Horde=Orda⟧ sia l'⟦Alliance=Alleanza⟧: amici nella causa di estirpare il male!\n\nPer l'Alba, <fratello/sorella> <mio/mia>!", "." },
  ["738518facb30d9b8"] = { "Ah, anche tu peschi! Ti serve forse un po' di addestramento? Magari posso insegnarti un paio di cose?", "." },
  ["73864487792c0737"] = { "Salve! Come posso aiutarti?", "." },
  ["738e8328a3943499"] = { "%s lancia un ruggito tremendo, allertando i nemici vicini!", "." },
  ["739c5ed2f9370bee"] = { "Lo avete deluso, mortaliii... Addio!", "." },
  ["739e3601af778732"] = { "Jenova Stoneshield, nel Distretto dei Nani, è quella che cerchi. Si occupa dei famigli dei cacciatori mentre loro si addestrano da suo padre.", "." },
  ["73a1e6b43084885b"] = { "Cosa sono i pegni d'amore?", "." },
  ["73a55584eaa8383d"] = { "Bene allora... Devi costruire una boa d'arcanite e piazzarla nell'oceano. Il mio pesciolino sarà attratto dalle emanazioni magiche. Quando si avvicinerà alla boa... BUM! Esploderà in un glorioso impulso di energia arcana, rivelando la vera forma del pesciolino. Inoltre, potresti incorrere o meno nell'ira di Neptulon. Direi 50 e 50.", "." },
  ["73a9d6cbf061bf7c"] = { "Chi osa attaccare l'⟦Silverwing Outpost=Avamposto degli Alargentea⟧?!?", "." },
  ["73b021aef3c66692"] = { "Uno a uno, quasi tutti quelli coinvolti in questa faccenda sono caduti preda di questi spettri. Capirò se deciderai di lasciar perdere, {name}.", "." },
  ["73bbbe00067e7af5"] = { "Fino a cosa, Eva? Devo saperlo.", "." },
  ["73bd28f9fa4c21a2"] = { "Ah, cerchi la saggezza di Ansekhwa. Cercalo sull'altura inferiore, nell'armeria di ⟦Thunder Bluff=Picco del Tuono⟧.", "." },
  ["73c1d7c79e6df47d"] = { "Shhh! Mi farai scoprire il nascondiglio!", "." },
  ["73c48bfa5c4800b6"] = { "Buliwyf, il maestro d'armi nanico dei Timberline Arms di ⟦Ironforge=Forgiardente⟧, insegna tirapugni, fucili, asce a una e a due mani e mazze a una e a due mani.\n\nBixi Wobblebonk, la maestra d'armi gnoma dei Timberline Arms di ⟦Ironforge=Forgiardente⟧, insegna balestre, pugnali e armi da lancio.\n\nWoo Ping, il maestro d'armi umano del Weller's Arsenal di ⟦Stormwind=Roccavento⟧, insegna balestre, pugnali, spade a una e a due mani, armi in asta e bastoni.", "." },
  ["73c64232049c98be"] = { "Quanti ufficiali dei Piccatonante sono ancora vivi, Drek'Thar?", "." },
  ["73cac74942f24bee"] = { "Quali ruoli?", "." },
  ["73d09ab6dc4853d7"] = { "Che bello che tu sia qui! Perché ho bisogno del tuo aiuto!!", "." },
  ["73d0cb3d2a16551d"] = { "Ora ti sto corrompendo...", "." },
  ["73d42fc439d14cc5"] = { "{name}, è bello vederti. La nostra guerra contro gli altri signori elementali infuria ancora, ma i tuoi sforzi ci aiutano ad assicurarci la vittoria.", "." },
  ["73d5c2b69e679a01"] = { "Non sappiamo molto dell'incendio della ⟦Shady Rest Inn=Locanda Ombracalma⟧, se non che la moglie e il figlio di James Hyal non sono riusciti a fuggire.\n\nSiamo riusciti a trascinare fuori James, ma da allora non è più lo stesso.\n\nAbbiamo molte piste ma poche prove. Speriamo che, grazie agli sforzi della guardia e all'aiuto vigile della gente di Theramore, riusciremo a far luce su questo terribile crimine.\n\nSe vuoi dare una mano alle indagini, ciò che resta della locanda si trova al confine con le ⟦Barrens=Savane⟧.", "." },
  ["73dae4caae73341d"] = { "Invasori in arrivo da sud!", "." },
  ["73e2820e1b504703"] = { "La Locanda del Fiero Leone di ⟦Goldshire=Borgodoro⟧ è buona quanto qualsiasi altra locanda da queste parti. Fai un salto e lascia che il locandiere Farley ti faccia sentire a casa.", "." },
  ["73e4dfcfd8a81ae9"] = { "È ora di preparare un Kalimdor Kocktail! Hic!", "." },
  ["73ed4b629197038b"] = { "Dov'è l'anziano Highpeak?", "." },
  ["73fe130f1e4ce4b0"] = { "<Tocca il cristallo instabile della fenditura.>", "." },
})
